// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        Reverter r = new Reverter();
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.Command{value: amount}(address(r), "") { ok = false; } catch { ok = true; }
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
